import{_ as t,o as a,c as n,ag as r}from"./chunks/framework.DTisvaUJ.js";const p=JSON.parse('{"title":"Speech recognition engines","description":"Compare Whisper, Parakeet, Haas and Qwen3-ASR in Mutelink: supported languages, download sizes and engine choices for your use.","frontmatter":{"description":"Compare Whisper, Parakeet, Haas and Qwen3-ASR in Mutelink: supported languages, download sizes and engine choices for your use.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/en/compare/speech-recognition"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Speech recognition engines | Mutelink"}],["meta",{"property":"og:description","content":"Compare Whisper, Parakeet, Haas and Qwen3-ASR in Mutelink: supported languages, download sizes and engine choices for your use."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/en/compare/speech-recognition"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Speech recognition engines | Mutelink"}],["meta",{"name":"twitter:description","content":"Compare Whisper, Parakeet, Haas and Qwen3-ASR in Mutelink: supported languages, download sizes and engine choices for your use."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/compare/speech-recognition"}]]},"headers":[],"relativePath":"en/compare/speech-recognition.md","filePath":"en/compare/speech-recognition.md"}'),o={name:"en/compare/speech-recognition.md"};function d(i,e,s,h,l,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="音声認識エンジンの比較" tabindex="-1">Speech recognition engines <a class="header-anchor" href="#音声認識エンジンの比較" aria-label="Permalink to &quot;Speech recognition engines {#音声認識エンジンの比較}&quot;">​</a></h1><p>Choose a recognition engine for each spoken language. Incoming speech can use the same local engines to transcribe other people.</p><h2 id="迷ったら" tabindex="-1">If you are unsure <a class="header-anchor" href="#迷ったら" aria-label="Permalink to &quot;If you are unsure {#迷ったら}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Spoken language</th><th>Recommendation</th></tr></thead><tbody><tr><td>Japanese</td><td>Parakeet Japanese TDT or Haas-ja</td></tr><tr><td>English</td><td>Parakeet English</td></tr><tr><td>Other languages or automatic language detection</td><td>Qwen3-ASR or Whisper turbo</td></tr><tr><td>Lower-spec PCs</td><td>Web Speech (cloud)</td></tr></tbody></table><h2 id="エンジンの一覧" tabindex="-1">Engine overview <a class="header-anchor" href="#エンジンの一覧" aria-label="Permalink to &quot;Engine overview {#エンジンの一覧}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Engine</th><th>Runs on</th><th>Languages</th><th>Download</th><th>Time relative to speech length</th><th>Features</th></tr></thead><tbody><tr><td>Parakeet Japanese TDT</td><td>This PC</td><td>Japanese</td><td>~1.0GB</td><td>~3.5%</td><td>Fast and accurate; punctuation included</td></tr><tr><td>Haas-ja</td><td>This PC</td><td>Japanese</td><td>~480MB</td><td>~13%</td><td>Slightly more accurate than Parakeet Japanese TDT on normal conversation; generates kanji and punctuation itself</td></tr><tr><td>Parakeet English</td><td>This PC</td><td>English and other European languages</td><td>~670MB</td><td>~5%</td><td>Fast; punctuation and capitalization. No Japanese, Chinese or Korean</td></tr><tr><td>Qwen3-ASR</td><td>This PC</td><td>52 languages including Japanese, English, Chinese and Korean</td><td>~1.0GB</td><td>~10–20%</td><td>Many languages in one model, with automatic language detection</td></tr><tr><td>Whisper turbo</td><td>This PC</td><td>Japanese, English, Chinese, Korean and more</td><td>~1.0GB</td><td>~30%</td><td>Automatic language detection; slower than the other local engines</td></tr><tr><td>Web Speech (Microsoft)</td><td>Cloud</td><td>Many languages</td><td>None</td><td>—</td><td>No model download; needs internet and sends audio to Microsoft</td></tr><tr><td>Google (unofficial, experimental)</td><td>Cloud</td><td>Many languages</td><td>None</td><td>—</td><td>Not an official API; may stop working without notice. Audio goes to Google</td></tr></tbody></table><ul><li>Local engines use only CPU, not GPU. Audio stays on your PC.</li><li>Times are indicative measurements on the developer’s Ryzen 7 7700. “~5%” means about 0.5 seconds to recognize 10 seconds of speech.</li><li>Haas-ja’s ~13% is rounded from the previous relative measurement (~3.6× Parakeet Japanese TDT) using ~3.5% as the baseline.</li><li>Only Qwen3-ASR and Whisper turbo allow the language to be set to Auto.</li></ul><h2 id="合成音声を聞かせた結果" tabindex="-1">Results on synthesized speech <a class="header-anchor" href="#合成音声を聞かせた結果" aria-label="Permalink to &quot;Results on synthesized speech {#合成音声を聞かせた結果}&quot;">​</a></h2><p>Each engine transcribed the same Qwen3-TTS/Irodori-TTS audio, and results were compared to the source text. This helps show <strong>differences in engine behavior</strong> on identical audio.</p><p>Cells show “mean error rate · exact matches/30.” Lower error rates are better.</p><h3 id="日本語-読みで比べたもの" tabindex="-1">Japanese (pronunciation-based comparison) <a class="header-anchor" href="#日本語-読みで比べたもの" aria-label="Permalink to &quot;Japanese (pronunciation-based comparison) {#日本語-読みで比べたもの}&quot;">​</a></h3><p>The app corrects Parakeet Japanese TDT’s kanji afterward, so both reference and recognized text are converted to hiragana here.</p><table tabindex="0"><thead><tr><th>Audio source</th><th>Whisper turbo</th><th>Qwen3-ASR</th><th>Parakeet Japanese TDT</th><th>Haas-ja</th></tr></thead><tbody><tr><td>Irodori-TTS</td><td>5.6% · 25/30</td><td>13.8% · 21/30</td><td>6.9% · 20/30</td><td>4.5% · 25/30</td></tr><tr><td>Qwen3-TTS</td><td>14.9% · 23/30</td><td>17.3% · 19/30</td><td>11.1% · 23/30</td><td>9.7% · 23/30</td></tr></tbody></table><h3 id="ほかの言語-qwen3-ttsの音声" tabindex="-1">Other languages (Qwen3-TTS audio) <a class="header-anchor" href="#ほかの言語-qwen3-ttsの音声" aria-label="Permalink to &quot;Other languages (Qwen3-TTS audio) {#ほかの言語-qwen3-ttsの音声}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Language</th><th>Whisper turbo</th><th>Qwen3-ASR</th><th>Parakeet English</th></tr></thead><tbody><tr><td>English</td><td>2.1% · 27/30</td><td>0.8% · 28/30</td><td>2.9% · 25/30</td></tr><tr><td>Chinese</td><td>5.4% · 25/30</td><td>0.3% · 29/30</td><td>Not supported</td></tr><tr><td>Korean</td><td>2.4% · 27/30</td><td>4.0% · 24/30</td><td>Not supported</td></tr><tr><td>German</td><td>3.9% · 26/30</td><td>4.4% · 25/30</td><td>4.7% · 23/30</td></tr><tr><td>Spanish</td><td>4.2% · 27/30</td><td>2.8% · 28/30</td><td>3.9% · 25/30</td></tr><tr><td>French</td><td>6.6% · 24/30</td><td>6.1% · 27/30</td><td>2.5% · 26/30</td></tr><tr><td>Italian</td><td>6.4% · 24/30</td><td>11.2% · 21/30</td><td>5.9% · 21/30</td></tr><tr><td>Portuguese</td><td>6.2% · 26/30</td><td>7.4% · 24/30</td><td>6.5% · 21/30</td></tr><tr><td>Russian</td><td>2.6% · 26/30</td><td>9.3% · 22/30</td><td>4.4% · 25/30</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Limitations</p><ul><li>These are synthetic voices, not human microphone recordings. Noise, real voices and individual speaking habits can change results.</li><li>Each language uses 30 short everyday sentences, AI-authored without native-speaker review.</li><li>Japanese, Chinese and Korean errors are counted per character; other languages per word. Number formatting (“3” versus “三”) and paraphrases also count as errors.</li><li>App post-processing such as kanji conversion and punctuation correction was not applied.</li><li>Cloud engines (Web Speech and Google) were not tested.</li></ul></div>',16)])])}const g=t(o,[["render",d]]);export{p as __pageData,g as default};
